def blockfeat_table(gi, starts, ww=None):
    # feature per (a,b) using actual extents
    T={}
    for a,ra in enumerate(starts):
        for b,cb in enumerate(starts):
            rnext = starts[a+1] if a+1<len(starts) else 7
            cnext = starts[b+1] if b+1<len(starts) else 7
            sub=[row[cb:cnext] for row in gi[ra:rnext]]
            vals=[v for r in sub for v in r]
            nsp=sum(1 for v in vals if v not in (0,1))
            n0=vals.count(0); n1=vals.count(1)
            T[(a,b)]=dict(n0=n0,n1=n1,nsp=nsp,area=len(vals),
                          n0min=min(n0,1),has1=int(n1>0),has0=int(n0>0),hassp=int(nsp>0))
    return T

